def trim_history(messages, budget):
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    for msg in messages:
        cost = msg["cost"]
        if cost < 0:
            raise ValueError("cost must be nonnegative")
    total_cost = 0
    suffix = []
    for msg in reversed(messages):
        cost = msg["cost"]
        total_cost += cost
        if total_cost > budget:
            break
        suffix.append(msg)
    suffix.reverse()
    return suffix

