def merge_tool_results(calls, results):
    # Build a mapping from id to content, keeping the last result for each id
    last_results = {}
    for item in results:
        id_ = item['id']
        if id_ in [c['id'] for c in calls]:
            last_results[id_] = item.get('content', '')

    # Reject duplicate call ids
    call_ids = [c['id'] for c in calls]
    if len(call_ids) != len(set(call_ids)):
        raise ValueError("Duplicate call ids")

    # Build output in call order
    output = []
    for call in calls:
        call_id = call['id']
        if call_id in last_results:
            output.append({'id': call_id, 'status': 'done', 'content': last_results[call_id]})
        else:
            output.append({'id': call_id, 'status': 'pending'})

    return output

