def summarize_usage(events):
    max_input = {}
    max_output = {}
    for event in events:
        rid = event['request_id']
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)
        if input_count < 0 or output_count < 0:
            raise ValueError("Negative count")
        if rid not in max_input or input_count > max_input[rid]:
            max_input[rid] = input_count
        if rid not in max_output or output_count > max_output[rid]:
            max_output[rid] = output_count
    total_input = sum(max_input.values())
    total_output = sum(max_output.values())
    return {'input': total_input, 'output': total_output}

