def trim_history(messages, budget):
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    for msg in messages:
        if msg['cost'] < 0:
            raise ValueError("cost must be nonnegative")

    n = len(messages)
    if n == 0:
        return []

    total = sum(msg['cost'] for msg in messages)
    if total <= budget:
        return list(messages)

    sum_suffix = 0
    start = n
    for i in range(n - 1, -1, -1):
        sum_suffix += messages[i]['cost']
        if sum_suffix <= budget:
            start = i
        else:
            break
    return list(messages[start:])

