def merge_tool_results(calls, results):
    # Validate calls: reject duplicate call ids
    seen = set()
    for call in calls:
        cid = call['id']
        if cid in seen:
            raise ValueError("duplicate call id")
        seen.add(cid)

    # Build the last result per id, ignoring unknown ids
    last_result = {}
    for res in results:
        if 'id' not in res:
            continue
        rid = res['id']
        if rid not in seen:
            continue
        last_result[rid] = res

    # Return one dict per call in call order
    output = []
    for call in calls:
        cid = call['id']
        res = last_result.get(cid)
        if res is not None:
            content = res.get('content', '')
            output.append({'id': cid, 'status': 'done', 'content': content})
        else:
            output.append({'id': cid, 'status': 'pending'})
    return output

