def trim_history(messages, budget):
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    for m in messages:
        cost = m.get('cost')
        if cost is None or cost < 0:
            raise ValueError("cost must be nonnegative")
    n = len(messages)
    if n == 0:
        return []
    # Compute suffix sums from the end
    suffix_sums = [0] * n
    running = 0
    for i in range(n - 1, -1, -1):
        running += messages[i]['cost']
        suffix_sums[i] = running
    # Find the smallest starting index whose suffix sum fits the budget
    for i in range(n):
        if suffix_sums[i] <= budget:
            return list(messages[i:])
    return []

